#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Provisions what the cloud skeleton needs: a GCP project, billing, Artifact Registry,
# service accounts, Workload Identity Federation, a budget alert, the Neon database and
# the MCP token in Secret Manager, the Cloud Scheduler job, and the GitHub variables the
# deploy workflow reads. Every stage checks what already exists, so the wizard is safe to
# re-run after a failure.
#
# Run from anywhere inside the repo:  ./scripts/provision.sh
#
# Writes non-secret values to .env (gitignored) so re-runs offer them as defaults.
# Secrets are never written to disk: they go to Secret Manager only.

GITHUB_REPO="montedeu/ml-research-radar"
WIF_POOL="github"
WIF_PROVIDER="github-oidc"
DEPLOY_SA_NAME="github-deployer"
RUNTIME_SA_NAME="radar-runtime"
SCHEDULER_SA_NAME="radar-scheduler"
BUDGET_NAME="ml-research-radar"
DB_SECRET="database-url"
TOKEN_SECRET="mcp-token"
COLLECT_JOB="radar-collect"
SCHEDULE_NAME="radar-collect-daily"
# 10:00 in Astana, Monday to Friday: arXiv's new records are out by about 08:30 there.
SCHEDULE_CRON="0 10 * * 1-5"
SCHEDULE_TZ="Asia/Almaty"

# run CMD... prints a command, runs it, and offers a retry if it fails.
# Declining stops the wizard: fix the cause and re-run.
run() {
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  until "$@"; do
    warn "That command failed (see the output above)."
    if ! confirm "Retry it?"; then
      warn "Stopping. Fix the problem and re-run; finished stages are skipped."
      exit 1
    fi
  done
}

# ask_default KEY "Prompt" DEFAULT is ask, falling back to DEFAULT on empty input.
ask_default() {
  local key="$1" prompt="$2" default="$3"
  ask "$key" "$prompt [$default]:"
  [[ -n "${!key}" ]] || printf -v "$key" '%s' "$default"
}

# store_secret NAME VALUE adds VALUE as a new version of the Secret Manager secret NAME
# and disables the versions it replaces: the free allowance counts active versions.
# From stdin, so the value is never on a command line or on disk. Not through run():
# its retry prompt would read from the pipe, and a retry would get an empty stdin.
store_secret() {
  local name="$1" value="$2" old
  if ! gcloud secrets describe "$name" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
    run gcloud secrets create "$name" --project="$GCP_PROJECT_ID" --replication-policy=automatic
  fi
  old=$(gcloud secrets versions list "$name" --project="$GCP_PROJECT_ID" \
          --filter=state=ENABLED --format='value(name)' 2>/dev/null || true)
  printf '  %s$ gcloud secrets versions add %s --data-file=-%s\n' "$DIM" "$name" "$RESET"
  until printf '%s' "$value" | gcloud secrets versions add "$name" \
          --project="$GCP_PROJECT_ID" --data-file=- --format=none; do
    warn "That command failed (see the output above)."
    confirm "Retry it?" || { warn "Stopping. Fix the problem and re-run."; exit 1; }
  done
  for version in $old; do
    run gcloud secrets versions disable "$version" --secret="$name" --project="$GCP_PROJECT_ID" --format=none
  done
  printf '  %s✓ stored%s %s in Secret Manager\n' "$GREEN" "$RESET" "$name"
}

# has_secret NAME: the secret exists and has an enabled version.
has_secret() {
  [[ -n "$(gcloud secrets versions list "$1" --project="$GCP_PROJECT_ID" \
             --filter=state=ENABLED --limit=1 --format='value(name)' 2>/dev/null)" ]]
}

run_wizard() {

TOTAL_STAGES=13

cd "$(dirname "$0")/.."

banner "ML Research Radar: provision GCP and Neon"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools: gcloud and gh"
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "The GitHub CLI is missing or not logged in."
  step "Install gh and run: gh auth login"
  pause "Press Enter when 'gh auth status' succeeds"
fi
gh auth status >/dev/null 2>&1 || { warn "gh still not logged in; stopping."; exit 1; }
command -v gcloud >/dev/null 2>&1 || { warn "gcloud is not installed: https://cloud.google.com/sdk/docs/install"; exit 1; }

ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null || true)
if [[ -n "$ACCOUNT" ]]; then
  say "gcloud is logged in as ${BOLD}${ACCOUNT}${RESET}."
  note "This Google account will own the project."
  if confirm "Log in with a different account?"; then run gcloud auth login; fi
else
  say "Log gcloud in with the Google account that should own the project."
  note "A browser tab opens; if it doesn't, open the URL gcloud prints."
  run gcloud auth login
fi
export CLOUDSDK_CORE_DISABLE_PROMPTS=1
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GCP project"
say "A project of its own, separate from fraud-api: its own service accounts, secrets"
say "and budget alert, and it can be deleted whole. The free tier is shared with every"
say "other project on the same billing account, so a second project adds no allowance."
say "Project IDs are global and permanent: 6–30 chars, lowercase letters, digits, hyphens."
note "Suggestion: research-radar-$(LC_ALL=C tr -dc 'a-z0-9' </dev/urandom | head -c 5)"
while :; do
  ask GCP_PROJECT_ID "Project ID:"
  [[ "$GCP_PROJECT_ID" =~ ^[a-z][a-z0-9-]{4,28}[a-z0-9]$ ]] && break
  warn "Not a valid project ID; try again."
done
if gcloud projects describe "$GCP_PROJECT_ID" >/dev/null 2>&1; then
  say "Project $GCP_PROJECT_ID already exists and you can see it; reusing it."
else
  run gcloud projects create "$GCP_PROJECT_ID" --name="ML Research Radar"
fi
GCP_PROJECT_NUMBER=$(gcloud projects describe "$GCP_PROJECT_ID" --format='value(projectNumber)')
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
set_var GCP_PROJECT_ID "$GCP_PROJECT_ID"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Billing account"
LINKED=$(gcloud billing projects describe "$GCP_PROJECT_ID" --format='value(billingEnabled)' 2>/dev/null || true)
if [[ "$LINKED" == "True" ]]; then
  GCP_BILLING_ACCOUNT=$(gcloud billing projects describe "$GCP_PROJECT_ID" --format='value(billingAccountName)')
  GCP_BILLING_ACCOUNT="${GCP_BILLING_ACCOUNT#billingAccounts/}"
  say "Billing is already enabled on $GCP_PROJECT_ID (account $GCP_BILLING_ACCOUNT)."
else
  say "Link the project to the billing account fraud-api already uses. Your open accounts:"
  gcloud billing accounts list --filter=open=true
  note "None listed? Create one at https://console.cloud.google.com/billing and re-run."
  while :; do
    ask GCP_BILLING_ACCOUNT "Billing ACCOUNT_ID (XXXXXX-XXXXXX-XXXXXX):"
    GCP_BILLING_ACCOUNT="${GCP_BILLING_ACCOUNT#billingAccounts/}"
    [[ "$GCP_BILLING_ACCOUNT" =~ ^[0-9A-F]{6}-[0-9A-F]{6}-[0-9A-F]{6}$ ]] && break
    warn "That doesn't look like a billing account ID; try again."
  done
  run gcloud billing projects link "$GCP_PROJECT_ID" --billing-account="$GCP_BILLING_ACCOUNT"
fi
write_env GCP_BILLING_ACCOUNT "$GCP_BILLING_ACCOUNT"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Enable APIs"
say "Enabling Cloud Run, Cloud Scheduler, Artifact Registry, IAM, STS, Budgets and"
say "Secret Manager (takes a minute)."
run gcloud services enable --project="$GCP_PROJECT_ID" \
  run.googleapis.com cloudscheduler.googleapis.com artifactregistry.googleapis.com \
  iam.googleapis.com iamcredentials.googleapis.com sts.googleapis.com \
  cloudresourcemanager.googleapis.com billingbudgets.googleapis.com \
  secretmanager.googleapis.com
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Artifact Registry repository"
ask_default GCP_REGION "Region for Cloud Run, Cloud Scheduler and Artifact Registry" "europe-west1"
ask_default GAR_REPOSITORY "Docker repository name" "research-radar"
if gcloud artifacts repositories describe "$GAR_REPOSITORY" --location="$GCP_REGION" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
  say "Repository $GAR_REPOSITORY already exists."
else
  run gcloud artifacts repositories create "$GAR_REPOSITORY" --project="$GCP_PROJECT_ID" \
    --location="$GCP_REGION" --repository-format=docker --description="ML Research Radar images"
fi
# The free allowance is 0.5 GB per billing account, shared with fraud-api's images, so
# fewer deploys are kept here than there.
KEEP_DEPLOYS=3
say "Applying the cleanup policy: keep the images of the last $KEEP_DEPLOYS deploys, delete the rest."
POLICY_FILE=$(mktemp --suffix=.json)
cat > "$POLICY_FILE" <<JSON
[
  {"name": "keep-recent", "action": {"type": "Keep"}, "mostRecentVersions": {"keepCount": $KEEP_DEPLOYS}},
  {"name": "delete-rest", "action": {"type": "Delete"}, "condition": {"tagState": "any"}}
]
JSON
run gcloud artifacts repositories set-cleanup-policies "$GAR_REPOSITORY" --project="$GCP_PROJECT_ID" \
  --location="$GCP_REGION" --policy="$POLICY_FILE" --no-dry-run
rm -f "$POLICY_FILE"
write_env GCP_REGION "$GCP_REGION"
write_env GAR_REPOSITORY "$GAR_REPOSITORY"
set_var GCP_REGION "$GCP_REGION"
set_var GAR_REPOSITORY "$GAR_REPOSITORY"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Service accounts and roles"
GCP_DEPLOY_SA="$DEPLOY_SA_NAME@$GCP_PROJECT_ID.iam.gserviceaccount.com"
GCP_RUNTIME_SA="$RUNTIME_SA_NAME@$GCP_PROJECT_ID.iam.gserviceaccount.com"
GCP_SCHEDULER_SA="$SCHEDULER_SA_NAME@$GCP_PROJECT_ID.iam.gserviceaccount.com"
say "Deployer  (used by GitHub Actions): $GCP_DEPLOY_SA"
say "Runtime   (identity of the Cloud Run jobs and service; reads secrets only): $GCP_RUNTIME_SA"
say "Scheduler (identity Cloud Scheduler starts the collect job with): $GCP_SCHEDULER_SA"
for pair in "$DEPLOY_SA_NAME:GitHub Actions deployer" "$RUNTIME_SA_NAME:Radar runtime" \
            "$SCHEDULER_SA_NAME:Radar scheduler"; do
  name="${pair%%:*}"
  if ! gcloud iam service-accounts describe "$name@$GCP_PROJECT_ID.iam.gserviceaccount.com" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
    run gcloud iam service-accounts create "$name" --project="$GCP_PROJECT_ID" --display-name="${pair#*:}"
  fi
done
note "New service accounts can take a few seconds to appear; retry if a binding fails."
say "Granting the deployer: Cloud Run Admin on the project (services, jobs, public access),"
say "Artifact Registry Writer on the repository only, Service Account User on the runtime SA only."
run gcloud projects add-iam-policy-binding "$GCP_PROJECT_ID" --condition=None --quiet \
  --member="serviceAccount:$GCP_DEPLOY_SA" --role=roles/run.admin --format=none
run gcloud artifacts repositories add-iam-policy-binding "$GAR_REPOSITORY" --project="$GCP_PROJECT_ID" \
  --location="$GCP_REGION" --member="serviceAccount:$GCP_DEPLOY_SA" \
  --role=roles/artifactregistry.writer --format=none
run gcloud iam service-accounts add-iam-policy-binding "$GCP_RUNTIME_SA" --project="$GCP_PROJECT_ID" \
  --member="serviceAccount:$GCP_DEPLOY_SA" --role=roles/iam.serviceAccountUser --format=none
# Project-wide because the collect job does not exist until the first deploy; the project
# holds nothing but the radar.
say "Granting the scheduler: Cloud Run Invoker on the project (it only starts jobs)."
run gcloud projects add-iam-policy-binding "$GCP_PROJECT_ID" --condition=None --quiet \
  --member="serviceAccount:$GCP_SCHEDULER_SA" --role=roles/run.invoker --format=none
write_env GCP_DEPLOY_SA "$GCP_DEPLOY_SA"
write_env GCP_RUNTIME_SA "$GCP_RUNTIME_SA"
set_var GCP_DEPLOY_SA "$GCP_DEPLOY_SA"
set_var GCP_RUNTIME_SA "$GCP_RUNTIME_SA"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Workload Identity Federation"
REPO_ID=$(gh api "repos/$GITHUB_REPO" --jq .id)
# The branch is part of the condition: a workflow on any other branch of this repo would
# otherwise get the deployer's rights too, whatever deploy.yml says about main.
CONDITION="assertion.repository=='$GITHUB_REPO' && assertion.repository_id=='$REPO_ID' && assertion.ref=='refs/heads/main'"
MAPPING="google.subject=assertion.sub,attribute.repository=assertion.repository,attribute.repository_id=assertion.repository_id,attribute.ref=assertion.ref"
say "Only GitHub Actions tokens from the main branch of $GITHUB_REPO (id $REPO_ID) will be accepted:"
note "$CONDITION"
if ! gcloud iam workload-identity-pools describe "$WIF_POOL" --location=global --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
  run gcloud iam workload-identity-pools create "$WIF_POOL" --location=global \
    --project="$GCP_PROJECT_ID" --display-name="GitHub Actions"
fi
if gcloud iam workload-identity-pools providers describe "$WIF_PROVIDER" --location=global \
     --workload-identity-pool="$WIF_POOL" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
  say "Provider exists; re-applying the mapping and condition."
  run gcloud iam workload-identity-pools providers update-oidc "$WIF_PROVIDER" --location=global \
    --workload-identity-pool="$WIF_POOL" --project="$GCP_PROJECT_ID" \
    --attribute-mapping="$MAPPING" --attribute-condition="$CONDITION"
else
  run gcloud iam workload-identity-pools providers create-oidc "$WIF_PROVIDER" --location=global \
    --workload-identity-pool="$WIF_POOL" --project="$GCP_PROJECT_ID" --display-name="GitHub OIDC" \
    --issuer-uri="https://token.actions.githubusercontent.com" \
    --attribute-mapping="$MAPPING" --attribute-condition="$CONDITION"
fi
POOL_PATH="projects/$GCP_PROJECT_NUMBER/locations/global/workloadIdentityPools/$WIF_POOL"
say "Letting identities from $GITHUB_REPO impersonate the deployer."
run gcloud iam service-accounts add-iam-policy-binding "$GCP_DEPLOY_SA" --project="$GCP_PROJECT_ID" \
  --role=roles/iam.workloadIdentityUser --format=none \
  --member="principalSet://iam.googleapis.com/$POOL_PATH/attribute.repository/$GITHUB_REPO"
GCP_WIF_PROVIDER="$POOL_PATH/providers/$WIF_PROVIDER"
write_env GCP_WIF_PROVIDER "$GCP_WIF_PROVIDER"
set_var GCP_WIF_PROVIDER "$GCP_WIF_PROVIDER"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Budget alert"
EXISTING_BUDGET=$(gcloud billing budgets list --billing-account="$GCP_BILLING_ACCOUNT" \
  --billing-project="$GCP_PROJECT_ID" --filter="displayName=$BUDGET_NAME" --format='value(name)' 2>/dev/null || true)
if [[ -n "$EXISTING_BUDGET" ]]; then
  say "Budget '$BUDGET_NAME' already exists: $EXISTING_BUDGET"
else
  CURRENCY=$(gcloud billing accounts describe "$GCP_BILLING_ACCOUNT" --format='value(currencyCode)' 2>/dev/null || true)
  [[ -n "$CURRENCY" ]] || ask_default CURRENCY "Billing account currency code" "USD"
  if [[ "$CURRENCY" == "USD" ]]; then
    BUDGET_AMOUNT=5
  else
    say "Your billing account is in $CURRENCY; the budget must use that currency."
    while :; do
      ask BUDGET_AMOUNT "Budget amount in $CURRENCY (about \$5):"
      [[ "$BUDGET_AMOUNT" =~ ^[0-9]+(\.[0-9]+)?$ ]] && break
      warn "Enter a number."
    done
  fi
  say "Creating a $BUDGET_AMOUNT $CURRENCY budget for this project, alerting at 50% and 100%."
  run gcloud billing budgets create --billing-account="$GCP_BILLING_ACCOUNT" \
    --billing-project="$GCP_PROJECT_ID" --display-name="$BUDGET_NAME" \
    --budget-amount="${BUDGET_AMOUNT}${CURRENCY}" \
    --filter-projects="projects/$GCP_PROJECT_NUMBER" \
    --threshold-rule=percent=0.5 --threshold-rule=percent=1.0
fi
warn "A budget only emails you; it stops nothing. What caps spend is one instance per"
note "service, scale to zero, and the limits the jobs enforce themselves."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Neon database → Secret Manager"
say "The connection string lives in Secret Manager as '$DB_SECRET'. Cloud Run reads it"
say "as DATABASE_URL through the runtime service account; the deploy workflow never sees it."
SKIP_NEON=0
if has_secret "$DB_SECRET"; then
  say "Secret $DB_SECRET already holds a connection string."
  confirm "Replace it with a new one?" || SKIP_NEON=1
fi
if (( ! SKIP_NEON )); then
  open_url "https://console.neon.tech/app/projects"
  step "Log in with the account fraud-api uses (the free plan allows many projects,"
  step "each with its own 1 GB of storage and its own compute hours)."
  step "New project → name: ml-research-radar, cloud: AWS, region: Europe (Frankfurt) eu-central-1 → Create."
  step "On the project dashboard click 'Connect'."
  step "Keep branch 'main', the default database and role; turn connection pooling OFF"
  step "(the direct string avoids PgBouncer quirks; one Cloud Run instance needs no pool)."
  step "Copy the connection string (postgresql://…neon.tech/…?sslmode=require…)."
  while :; do
    ask_secret DATABASE_URL "Paste the connection string (hidden):"
    [[ "$DATABASE_URL" =~ ^postgres(ql)?://.+@.+ ]] && break
    warn "That doesn't look like a postgresql:// connection string; try again."
  done
  store_secret "$DB_SECRET" "$DATABASE_URL"
  unset DATABASE_URL
fi
say "Letting the runtime service account (only) read the secret."
run gcloud secrets add-iam-policy-binding "$DB_SECRET" --project="$GCP_PROJECT_ID" \
  --member="serviceAccount:$GCP_RUNTIME_SA" --role=roles/secretmanager.secretAccessor --format=none
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "MCP server token → Secret Manager"
say "The MCP server answers only requests that carry this token; it is generated here"
say "and stored as '$TOKEN_SECRET'. It is not shown: read it back when you connect Claude."
SKIP_TOKEN=0
if has_secret "$TOKEN_SECRET"; then
  say "Secret $TOKEN_SECRET already holds a token."
  warn "Replacing it disconnects every client configured with the old one."
  confirm "Generate a new token?" || SKIP_TOKEN=1
fi
if (( ! SKIP_TOKEN )); then
  MCP_TOKEN=$(openssl rand -hex 32)
  store_secret "$TOKEN_SECRET" "$MCP_TOKEN"
  unset MCP_TOKEN
fi
run gcloud secrets add-iam-policy-binding "$TOKEN_SECRET" --project="$GCP_PROJECT_ID" \
  --member="serviceAccount:$GCP_RUNTIME_SA" --role=roles/secretmanager.secretAccessor --format=none
note "To read it later:"
note "  gcloud secrets versions access latest --secret=$TOKEN_SECRET --project=$GCP_PROJECT_ID"
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Cloud Scheduler: the daily collect job"
say "One scheduler job starts the Cloud Run job '$COLLECT_JOB' at $SCHEDULE_CRON ($SCHEDULE_TZ)."
if gcloud scheduler jobs describe "$SCHEDULE_NAME" --location="$GCP_REGION" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
  say "Scheduler job $SCHEDULE_NAME already exists; leaving it as is."
else
  warn "How many scheduler jobs are free per billing account was not confirmed from the docs."
  open_url "https://cloud.google.com/scheduler/pricing"
  step "Read the free allowance and the price per job beyond it."
  step "Count the scheduler jobs your other projects already have on this billing account."
  if confirm "Create the scheduler job?"; then
    run gcloud scheduler jobs create http "$SCHEDULE_NAME" --project="$GCP_PROJECT_ID" \
      --location="$GCP_REGION" --schedule="$SCHEDULE_CRON" --time-zone="$SCHEDULE_TZ" \
      --uri="https://run.googleapis.com/v2/projects/$GCP_PROJECT_ID/locations/$GCP_REGION/jobs/$COLLECT_JOB:run" \
      --http-method=POST --oauth-service-account-email="$GCP_SCHEDULER_SA" \
      --description="Starts the radar's daily collection"
    note "Until the first deploy creates '$COLLECT_JOB', a scheduled run fails with 404; that is expected."
  else
    SKIPPED+=("Cloud Scheduler job $SCHEDULE_NAME (re-run this wizard to create it)")
  fi
fi
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "GitHub secret scanning push protection"
PP=$(gh api "repos/$GITHUB_REPO" --jq '.security_and_analysis.secret_scanning_push_protection.status')
if [[ "$PP" == "enabled" ]]; then
  say "Push protection is already on for $GITHUB_REPO."
else
  say "Push protection is $PP."
  if confirm "Turn on secret scanning and push protection?"; then
    run gh api -X PATCH "repos/$GITHUB_REPO" --silent --input - <<'JSON'
{"security_and_analysis": {"secret_scanning": {"status": "enabled"},
                           "secret_scanning_push_protection": {"status": "enabled"}}}
JSON
  else
    SKIPPED+=("push protection: Settings → Code security → Push protection")
  fi
fi
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Prove WIF works from GitHub Actions"
say "Only a workflow on main can authenticate, so the proof runs on main: the 'WIF check'"
say "workflow signs in as the deployer and reads the image repository. It deploys nothing."
if ! gh workflow view wif-check.yml --repo "$GITHUB_REPO" >/dev/null 2>&1; then
  warn "The 'WIF check' workflow is not on main yet; merge it, then re-run this wizard."
  SKIPPED+=("WIF proof: gh workflow run wif-check.yml --ref main")
elif confirm "Run the WIF check on main now?"; then
  latest_run() {
    gh run list --repo "$GITHUB_REPO" --workflow wif-check.yml --limit 1 \
      --json databaseId --jq '.[0].databaseId // empty' 2>/dev/null || true
  }
  # The run started here is the first one with an id other than this.
  BEFORE=$(latest_run)
  run gh workflow run wif-check.yml --repo "$GITHUB_REPO" --ref main
  say "Waiting for the run to start…"
  RUN_ID=""
  for _ in $(seq 1 30); do
    RUN_ID=$(latest_run)
    [[ -n "$RUN_ID" && "$RUN_ID" != "$BEFORE" ]] && break
    RUN_ID=""
    sleep 3
  done
  if [[ -z "$RUN_ID" ]]; then
    warn "No run appeared; check the Actions tab."
    SKIPPED+=("WIF proof: gh workflow run wif-check.yml --ref main, then watch it in Actions")
  elif gh run watch "$RUN_ID" --repo "$GITHUB_REPO" --exit-status; then
    printf '  %s✓ WIF auth works%s: https://github.com/%s/actions/runs/%s\n' "$GREEN" "$RESET" "$GITHUB_REPO" "$RUN_ID"
  else
    warn "The WIF check failed: https://github.com/$GITHUB_REPO/actions/runs/$RUN_ID"
    SKIPPED+=("WIF check run $RUN_ID failed: read its log, fix the provider or the bindings above")
  fi
else
  SKIPPED+=("WIF proof: gh workflow run wif-check.yml --ref main")
fi
pause

# Last on purpose: the deploy workflow is skipped until this is set, so a merge to main
# while the stages above are half done deploys nothing.
if [[ "$(gh variable get DEPLOY_ENABLED --repo "$GITHUB_REPO" 2>/dev/null || true)" == "true" ]]; then
  say "Deploys are already on (DEPLOY_ENABLED is true); this wizard leaves that as it is."
  (( ${#SKIPPED[@]} )) && warn "Some steps were skipped (listed next); deploys stay on regardless."
elif (( ${#SKIPPED[@]} )); then
  warn "Some steps were skipped (listed next), so deploys stay off."
  note "Finish them and re-run this wizard, or turn deploys on yourself:"
  note "  gh variable set DEPLOY_ENABLED --body true"
else
  set_var DEPLOY_ENABLED true
fi

finish
say "GitHub variables: GCP_PROJECT_ID GCP_REGION GAR_REPOSITORY GCP_DEPLOY_SA GCP_RUNTIME_SA GCP_WIF_PROVIDER"
say "Secret Manager:   $DB_SECRET, $TOKEN_SECRET (read by $RUNTIME_SA_NAME)"
say "Next: run the Deploy workflow on main (gh workflow run deploy.yml); it creates the jobs and the MCP server."
printf '\n'
}

run_wizard "$@"; exit
